function loadOcrLibrary(){if(window.Tesseract?.createWorker)return Promise.resolve();if(ocrLibraryPromise)return ocrLibraryPromise;ocrLibraryPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=OCR_CDN;s.async=true;s.onload=()=>window.Tesseract?.createWorker?resolve():reject(Error('文字認識ライブラリを読み込めません'));s.onerror=()=>reject(Error('文字認識ライブラリを読み込めません'));document.head.appendChild(s)}).catch(e=>{ocrLibraryPromise=null;throw e});return ocrLibraryPromise}
