const fchStyle=document.createElement('style');fchStyle.id='fch-sports-v3';fchStyle.textContent='\n/* V3: premium football magazine / light blue FotMob-inspired interface */\n.fch-kicker{letter-spacing:.17em;font-size:9px;font-weight:900;color:#3987b4;margin-bottom:5px}\n.fch-squad-top,.fch-social-header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 13px}\n.fch-squad-top h2,.fch-social-header h2{margin:0;font-size:22px;color:#143653;font-weight:900;letter-spacing:-.025em}\n.fch-squad-top p,.fch-social-header p{margin:4px 0 0;line-height:1.5}\n.fch-squad-top .btn,.fch-social-header .btn{white-space:nowrap;flex-shrink:0}\n.fch-squad-tab{display:flex;background:#cbe9fc;padding:5px;border-radius:14px;gap:5px;margin:14px 0}\n.fch-squad-tab button{flex:1;border:0;border-radius:10px;background:transparent;padding:13px 5px;color:#2b709d;font-weight:850;font-size:12px}\n.fch-squad-tab button.selected{background:#fff;color:#0478bd;box-shadow:0 2px 10px #25628f25}\n.fch-roster-controls{display:flex;gap:7px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:11px 0}\n.fch-roster-controls .segmented{max-width:100%;flex:1}\n.fch-roster-controls button{font-size:11px}\n.fch-roster-section{background:#fff;border:1px solid #d1e6f3;border-radius:19px;overflow:hidden;margin:13px 0;box-shadow:0 6px 20px #1e6ca70a}\n.fch-roster-heading{display:flex;justify-content:space-between;align-items:center;padding:15px 17px 10px;font-size:15px;font-weight:900;color:#163a59}\n.fch-roster-heading span{font-size:11px;font-weight:500;color:#7b93a5;padding-right:24px}\n.fch-roster-player{display:flex;width:100%;align-items:center;gap:12px;padding:13px 15px;background:transparent;border:0;border-top:1px solid #ecf3f7;color:#163b57;text-align:left;transition:background .15s}\n.fch-roster-player:active,.fch-roster-player:hover{background:#f0faff}\n.fch-roster-avatar{height:48px;width:48px;border-radius:50%;background:linear-gradient(135deg,#d9f0ff,#96c7ec);border:1.5px solid #c7e4f5;display:grid;place-items:center;flex:none;overflow:hidden;font-size:11px;font-weight:900;color:#237ab2}\n.fch-roster-avatar img{width:100%;height:100%;object-fit:cover}\n.fch-roster-bio{display:flex;flex-direction:column;gap:6px;flex:1;min-width:0}\n.fch-roster-name{font-size:14px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.fch-number{color:#5491b4;font-weight:650;margin-right:2px}\n.fch-roster-country{font-size:11px;color:#6c8294;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.fch-dot{color:#a6b9c9;margin:0 2px}.fch-roster-age{color:#385c77;font-size:13px;min-width:20px;text-align:right}.fch-row-chevron{color:#afc4d4;font-size:18px}\n.fch-tactics-area{padding:7px 0}\n.fch-tactics-area .pitch{height:425px}\n.fch-tactics-area .pitch-player{background:#075b9be8;border-color:#ace2ff}\n.fch-social-filters{display:flex;align-items:center;gap:5px;padding:5px 0 11px;overflow:auto;scrollbar-width:none}\n.fch-social-filters::-webkit-scrollbar{display:none}\n.fch-social-filters button{border:0;border-radius:12px;padding:11px 16px;background:transparent;color:#477896;font-weight:750;white-space:nowrap}\n.fch-social-filters button.selected{background:#0786cd;color:#fff;box-shadow:0 3px 9px #1779b12a}\n.fch-social-post{background:#fff;color:#163c5a;border-radius:18px;overflow:hidden;margin:12px 0 20px;box-shadow:0 3px 17px #135d9320;border:1px solid #d4e7f3}\n.fch-post-header{display:flex;align-items:center;gap:10px;padding:14px 15px 9px}\n.fch-post-header .avatar{width:39px;height:39px;border-color:#bee6fb}\n.fch-post-author{min-width:0;flex:1;display:flex;flex-direction:column;gap:3px}\n.fch-post-author strong{font-size:13px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}\n.fch-post-author span{font-size:10px;color:#7896a9}\n.fch-post-kind{font-size:9px;font-weight:900;letter-spacing:.1em;background:#e5f6ff;padding:7px 9px;color:#1686c9;border-radius:6px}\n.fch-post-copy{padding:7px 16px 14px}.fch-post-copy strong{font-size:14px}.fch-post-copy p{margin:6px 0 0;font-size:13px;line-height:1.65;white-space:pre-wrap;color:#42627a}\n.fch-poster{position:relative;isolation:isolate;min-height:410px;overflow:hidden;color:#fff;background:linear-gradient(145deg,#0a4775 0%,#0876b9 55%,#06385f 100%)}\n.fch-poster-grid{position:absolute;z-index:-1;inset:0;background:repeating-linear-gradient(135deg,transparent 0 48px,#ffffff09 48px 105px);pointer-events:none}\n.fch-poster-intro{display:flex;gap:12px;align-items:center;padding:24px 22px 0;position:relative;z-index:3}\n.fch-poster-intro .club-badge{background:#fff;width:44px;height:44px;font-size:12px}\n.fch-poster-intro>div{display:flex;flex-direction:column;gap:6px}.fch-poster-intro strong{font-size:14px;letter-spacing:.12em}.fch-poster-intro span{font-size:10px;letter-spacing:.13em;color:#bde8ff}\n.fch-poster-kicker{font-size:9px;letter-spacing:.20em;color:#a8defd;padding:28px 22px 0;position:relative;z-index:3}\n.fch-poster-headline{font-size:clamp(34px,9vw,48px);font-weight:1000;letter-spacing:-.04em;line-height:1.05;padding:5px 22px 10px;position:relative;z-index:3}\n.fch-poster-list{position:relative;z-index:3;max-width:63%;font-weight:800;font-size:13px;line-height:1.2;padding:5px 18px 20px 22px;display:grid;gap:6px;text-shadow:0 1px 9px #033f60}\n.fch-poster-list div{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.fch-poster-list span{font-size:10px;opacity:.6;margin-right:8px}\n.fch-lineup-person{position:absolute;right:-7%;bottom:38px;height:62%;width:57%;object-fit:cover;object-position:center;filter:drop-shadow(-15px 8px 18px #002d46a0);mask-image:linear-gradient(to right,transparent 0%,black 34%);opacity:.92;z-index:1}\n.fch-poster-subs{position:relative;z-index:4;padding:14px 22px;background:#013a60bb;border-top:1px solid #ffffff44;display:flex;flex-direction:column;gap:7px;font-size:10px;line-height:1.6;max-width:100%}\n.fch-poster-subs strong{font-size:12px;letter-spacing:.17em;color:#bcf0ff}\n.fch-poster-signoff{position:relative;z-index:4;font-size:9px;letter-spacing:.19em;font-weight:750;color:#b3e5ff;padding:13px 22px 20px}\n.fch-goal-poster{min-height:440px;background:radial-gradient(circle at 80% 78%,#18a7f1 0%,#086ea9 44%,#003a70 100%)}\n.fch-goal-title{position:absolute;z-index:1;top:17px;left:1%;font-size:clamp(80px,27vw,190px);font-weight:1000;line-height:.92;letter-spacing:-.10em;color:#c4f4ff;text-shadow:0 6px 30px #0cf4ff88}\n.fch-goal-photo{position:absolute;right:-10%;bottom:0;height:78%;width:88%;object-fit:cover;object-position:center 23%;mask-image:linear-gradient(to right,transparent 0%,black 33%);z-index:1}\n.fch-poster-upload{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:1;filter:brightness(.79)}\n.fch-goal-poster:after,.fch-transfer-poster:after,.fch-result-poster:after{content:"";position:absolute;inset:45% 0 0;background:linear-gradient(0deg,#03284cf2,transparent);pointer-events:none;z-index:1}\n.fch-poster-bottom{position:absolute;bottom:17px;left:20px;z-index:3;display:flex;flex-direction:column;gap:5px;text-shadow:0 2px 5px #004172}\n.fch-poster-bottom>span{font-size:11px;color:#a5e0fc}.fch-poster-bottom strong{font-size:29px;font-weight:1000}.fch-poster-bottom small{font-size:10px;letter-spacing:.05em}\n.fch-poster-crest{position:absolute;right:18px;bottom:15px;z-index:3}.fch-poster-crest .club-badge{background:#fff}\n.fch-result-poster{min-height:330px;background:linear-gradient(130deg,#043c76,#116ca4)}\n.fch-result-poster.loss{background:linear-gradient(130deg,#15365b,#487fa7)}.fch-result-poster.win{background:linear-gradient(130deg,#075fa0,#00a2ce)}\n.fch-poster-center{position:relative;z-index:3;text-align:center;padding:58px 15px 55px;display:flex;flex-direction:column;gap:11px}.fch-poster-center span{font-size:10px;letter-spacing:.2em;color:#c2effd}.fch-poster-center div{font-weight:1000;font-size:clamp(64px,19vw,100px);line-height:1}.fch-poster-center strong{font-size:12px}\n.fch-transfer-poster{min-height:390px;background:linear-gradient(130deg,#0278a9,#063e7d)}\n.fch-transfer-person{position:absolute;right:-8%;bottom:0;height:78%;width:75%;object-fit:cover;mask-image:linear-gradient(to right,transparent,#000 40%);z-index:1}\n.fch-transfer-title{position:relative;z-index:3;padding:105px 20px 0;font-size:clamp(36px,10vw,57px);font-weight:1000;letter-spacing:-.06em}.fch-transfer-name{position:relative;z-index:3;padding:8px 22px 30px;font-size:21px;font-weight:850;max-width:78%}\n.fch-photo-post{max-height:520px;background:#07365b}.fch-photo-post img{width:100%;display:block;max-height:520px;object-fit:cover}\n.fch-post-engagement{padding:12px 15px;display:flex;gap:12px;align-items:center;border-top:1px solid #e8f1f6}\n.fch-post-action{border:0;background:transparent;color:#57758b;padding:3px;font-size:12px}.fch-post-action.liked{color:#e84974}.fch-post-action:disabled{opacity:1;cursor:default}\n.fch-post-engagement>span{margin-left:auto;color:#7894a5;font-size:10px}\n.fch-comments{background:#f2faff;border-top:1px solid #d5eaf5;padding:15px}\n.fch-comments-title{font-weight:850;color:#225374;margin:0 0 12px;font-size:14px}.fch-comments-title small{color:#5c92ae;font-size:10px;margin-left:6px;font-weight:500}\n.fch-comment-row{display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-top:1px solid #dfeff7}\n.fch-comment-avatar{width:29px;height:29px;border-radius:50%;display:grid;place-items:center;background:#d6edfb;color:#1778b9;flex:none;font-weight:850;font-size:11px}\n.fch-comment-content{flex:1}.fch-comment-content>div{display:flex;align-items:baseline;gap:8px}.fch-comment-content strong{font-size:12px}.fch-comment-content span,.fch-comment-content small{color:#7299b0;font-size:10px}.fch-comment-content p{font-size:12px;line-height:1.65;margin:5px 0;color:#335a77}\n.fch-fiction-disclaimer{border-top:1px solid #e5f0f6;color:#93a9b8;font-size:9px;padding:9px 14px;text-align:center}\n@media(max-width:380px){.fch-poster-list{font-size:11px}.fch-lineup-person{opacity:.6}.fch-roster-player{gap:8px;padding:11px}.fch-roster-name{font-size:13px}.fch-squad-top .btn{font-size:11px}}\n';fchStyle.textContent += '.segmented button.selected{background:#1185ce!important;color:#fff!important;border-color:#57b8f0!important}.segmented button{background:#e7f6ff!important;color:#2c6b9c!important;border-color:#c9e6f7!important}.segmented button.selected{background:#1185ce!important;color:#fff!important}';fchStyle.textContent += '.bottom-nav .nav-ico svg{width:22px;height:22px;display:block;margin:0 auto}.fch-social-filters .fch-sort-toggle{margin-left:auto;border:1px solid #bad8ec;background:#fff;color:#367caa;font-size:11px;padding:10px 8px;border-radius:10px}';document.head.appendChild(fchStyle);

